using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Sigov.Api.Middlewares; using Sigov.Application.Agro.InfraestruturaRural; using Sigov.Application.Common; using Sigov.Domain.Common;
namespace Sigov.Api.Controllers;
[ApiController,Authorize,RequireModule("agro")] public sealed class AgroInfraestruturaRuralController:ControllerBase{private readonly IAgroEstradaVicinalService _e;private readonly IAgroPontoCriticoService _p;private readonly IAgroOcorrenciaRuralService _o;private readonly IAgroManutencaoRuralService _m; public AgroInfraestruturaRuralController(IAgroEstradaVicinalService e,IAgroPontoCriticoService p,IAgroOcorrenciaRuralService o,IAgroManutencaoRuralService m){_e=e;_p=p;_o=o;_m=m;} [HttpGet("api/agro/estradas-vicinais")] public async Task<ActionResult<ApiResponse<PagedResult<AgroEstradaVicinalResponse>>>> Estradas([FromQuery]AgroEstradaVicinalFiltro f,CancellationToken ct)=>FromResult(await _e.ListarAsync(f,ct)); [HttpGet("api/agro/estradas-vicinais/{id:long}")] public async Task<ActionResult<ApiResponse<AgroEstradaVicinalResponse>>> Estrada(long id,CancellationToken ct)=>FromResult(await _e.ObterAsync(id,ct)); [HttpPost("api/agro/estradas-vicinais")] public async Task<ActionResult<ApiResponse<long>>> CriarEstrada([FromBody]AgroEstradaVicinalCreateRequest r,CancellationToken ct)=>FromResult(await _e.CriarAsync(r,ct)); [HttpPut("api/agro/estradas-vicinais/{id:long}")] public async Task<ActionResult<ApiResponse<object>>> AtualizarEstrada(long id,[FromBody]AgroEstradaVicinalUpdateRequest r,CancellationToken ct)=>FromResult(await _e.AtualizarAsync(id,r,ct)); [HttpDelete("api/agro/estradas-vicinais/{id:long}")] public async Task<ActionResult<ApiResponse<object>>> ExcluirEstrada(long id,CancellationToken ct)=>FromResult(await _e.ExcluirAsync(id,ct)); [HttpGet("api/agro/pontos-criticos")] public async Task<ActionResult<ApiResponse<PagedResult<AgroPontoCriticoResponse>>>> Pontos([FromQuery]AgroEstradaVicinalFiltro f,CancellationToken ct)=>FromResult(await _p.ListarAsync(f,ct)); [HttpPost("api/agro/estradas-vicinais/{id:long}/pontos-criticos")] public async Task<ActionResult<ApiResponse<long>>> CriarPonto(long id,[FromBody]AgroPontoCriticoCreateRequest r,CancellationToken ct)=>FromResult(await _p.CriarAsync(id,r,ct)); [HttpPut("api/agro/pontos-criticos/{id:long}")] public async Task<ActionResult<ApiResponse<object>>> AtualizarPonto(long id,[FromBody]AgroPontoCriticoCreateRequest r,CancellationToken ct)=>FromResult(await _p.AtualizarAsync(id,r,ct)); [HttpPost("api/agro/pontos-criticos/{id:long}/resolver")] public async Task<ActionResult<ApiResponse<object>>> ResolverPonto(long id,CancellationToken ct)=>FromResult(await _p.ResolverAsync(id,ct)); [HttpGet("api/agro/ocorrencias-rurais")] public async Task<ActionResult<ApiResponse<PagedResult<AgroOcorrenciaRuralResponse>>>> Ocorrencias([FromQuery]AgroEstradaVicinalFiltro f,CancellationToken ct)=>FromResult(await _o.ListarAsync(f,ct)); [HttpGet("api/agro/ocorrencias-rurais/{id:long}")] public async Task<ActionResult<ApiResponse<AgroOcorrenciaRuralResponse>>> Ocorrencia(long id,CancellationToken ct)=>FromResult(await _o.ObterAsync(id,ct)); [HttpPost("api/agro/ocorrencias-rurais")] public async Task<ActionResult<ApiResponse<long>>> CriarOcorrencia([FromBody]AgroOcorrenciaRuralCreateRequest r,CancellationToken ct)=>FromResult(await _o.CriarAsync(r,ct)); [HttpPut("api/agro/ocorrencias-rurais/{id:long}")] public async Task<ActionResult<ApiResponse<object>>> AtualizarOcorrencia(long id,[FromBody]AgroOcorrenciaRuralCreateRequest r,CancellationToken ct)=>FromResult(await _o.AtualizarAsync(id,r,ct)); [HttpPost("api/agro/ocorrencias-rurais/{id:long}/resolver")] public async Task<ActionResult<ApiResponse<object>>> ResolverOcorrencia(long id,CancellationToken ct)=>FromResult(await _o.ResolverAsync(id,ct)); [HttpPost("api/agro/ocorrencias-rurais/{id:long}/cancelar")] public async Task<ActionResult<ApiResponse<object>>> CancelarOcorrencia(long id,CancellationToken ct)=>FromResult(await _o.CancelarAsync(id,ct)); [HttpGet("api/agro/manutencoes-rurais")] public async Task<ActionResult<ApiResponse<PagedResult<AgroManutencaoRuralResponse>>>> Manutencoes([FromQuery]AgroEstradaVicinalFiltro f,CancellationToken ct)=>FromResult(await _m.ListarAsync(f,ct)); [HttpPost("api/agro/manutencoes-rurais")] public async Task<ActionResult<ApiResponse<long>>> CriarManutencao([FromBody]AgroManutencaoRuralCreateRequest r,CancellationToken ct)=>FromResult(await _m.CriarAsync(r,ct)); [HttpPost("api/agro/manutencoes-rurais/{id:long}/executar")] public async Task<ActionResult<ApiResponse<object>>> ExecutarManutencao(long id,CancellationToken ct)=>FromResult(await _m.ExecutarAsync(id,ct)); [HttpPost("api/agro/manutencoes-rurais/{id:long}/cancelar")] public async Task<ActionResult<ApiResponse<object>>> CancelarManutencao(long id,CancellationToken ct)=>FromResult(await _m.CancelarAsync(id,ct)); private ActionResult<ApiResponse<T>> FromResult<T>(Result<T> r){if(r.IsSuccess&&r.Value is not null)return Ok(ApiResponse<T>.Ok(r.Value)); if(r.Error=="403")return Forbid(); if(r.Error?.Contains("autenticado",StringComparison.OrdinalIgnoreCase)==true)return Unauthorized(ApiResponse<T>.Fail(r.Error)); if(r.Error?.Contains("não encontr",StringComparison.OrdinalIgnoreCase)==true)return NotFound(ApiResponse<T>.Fail(r.Error)); return UnprocessableEntity(ApiResponse<T>.Fail(r.Error??"Requisição inválida."));} private ActionResult<ApiResponse<object>> FromResult(Result r){if(r.IsSuccess)return Ok(ApiResponse<object>.Ok(new{ok=true})); if(r.Error=="403")return Forbid(); if(r.Error?.Contains("autenticado",StringComparison.OrdinalIgnoreCase)==true)return Unauthorized(ApiResponse<object>.Fail(r.Error)); return UnprocessableEntity(ApiResponse<object>.Fail(r.Error??"Requisição inválida."));}}
